import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    if n == 1:
        return 1
    count = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
        d += 1
    return count

def solve_search(limit):
    solutions = {}
    print(f"Starting computational search up to n = {limit}")
    for n in range(1, limit + 1):
        divs = get_divisors(n)

        # Condition: n must have at least 5 positive divisors
        if len(divs) < 5:
            continue

        # a, b, c are the 2nd, 3rd, and 5th smallest divisors (index 1, 2, 4)
        a = divs[1]
        b = divs[2]
        c = divs[4]

        # Check the core equation: n = ab + ac + bc
        calculated_n = a * b + a * c + b * c

        if calculated_n == n:
            tau_n = len(divs)
            solutions[n] = tau_n
            print(f"Found solution: n = {n}, tau(n) = {tau_n}. Divisors: {divs}")

    return solutions

# Run the search up to 300
search_limit = 300
solutions = solve_search(search_limit)

print("\n--- Results Summary ---")
for n, tau_n in solutions.items():
    print(f"n = {n}, tau(n) = {tau_n}")

# Verification of known solutions:
# n=36: Divs: [1, 2, 3, 4, 6, 9, 12, 18, 36]. a=2, b=3, c=6. 2*3+2*6+3*6 = 6+12+18 = 36. Correct.
# n=56: Divs: [1, 2, 4, 7, 8, 14, 28, 56]. a=2, b=4, c=8. 2*4+2*8+4*8 = 8+16+32 = 56. Correct.

